ytics-panel header h3,.report-table-panel h3{margin-top:.15rem;color:#173943;font-size:.95rem;font-weight:850}.analytics-panel header>small{color:#86969b;font-size:.62rem}.trend-chart{display:flex;height:12rem;align-items:flex-end;gap:.6rem;border-bottom:1px solid #dae4e4;background:repeating-linear-gradient(to bottom,transparent 0,transparent calc(25% - 1px),#edf2f2 25%)}.trend-chart>div{position:relative;display:flex;flex:1;height:100%;align-items:flex-end;justify-content:center}.trend-chart i{display:block;width:min(2.7rem,65%);min-height:4px;border-radius:.45rem .45rem 0 0;background:linear-gradient(180deg,#1db39a,#08786d)}.trend-chart b{position:absolute;bottom:calc(100% + .2rem);display:none;white-space:nowrap;border-radius:.35rem;background:#173943;padding:.25rem .4rem;color:#fff;font-size:.56rem}.trend-chart>div:hover b{display:block}.trend-chart small{position:absolute;top:calc(100% + .25rem);white-space:nowrap;color:#7f9197;font-size:.53rem}.distribution-list{display:grid;gap:.75rem}.distribution-list>div{position:relative;padding-right:2.6rem}.distribution-list p{display:flex;justify-content:space-between;gap:.5rem;color:#334f57;font-size:.66rem}.distribution-list p span{font-weight:800}.distribution-list p small{display:block;color:#94a2a6;font-weight:500}.distribution-list p strong{font-size:.64rem}.distribution-list>div>i{display:block;height:.42rem;margin-top:.3rem;overflow:hidden;border-radius:99px;background:#edf2f2}.distribution-list>div>i b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#176bd5,#18a88f)}.distribution-list em{position:absolute;right:0;bottom:-.05rem;color:#60777e;font-size:.58rem;font-style:normal;font-weight:800}.leaders-panel{grid-column:1/-1}.leader-list{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:.6rem}.leader-list>div{display:grid;grid-template-columns:1.7rem 1fr;gap:.5rem;border:1px solid #e3ebea;border-radius:.8rem;padding:.65rem}.leader-list>div>span{display:grid;width:1.